44	const PROCESSING_FEE = 5;
45	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
46	
47	const BASE_PREMIUMS = {
48	  sword: 100,
49	  amulet: 60,
50	  staff: 80,
51	  potion: 40,
52	  rune: 25,
53	  moonstone: 25,
54	} as const satisfies Record<string, number>;
55	
56	export type InsurableItemType = keyof typeof BASE_PREMIUMS;
57	
58	const basePremiumFor = (item: Item): number =>
59	  BASE_PREMIUMS[item.type as InsurableItemType];
60	
61	const COMPONENT_BLOCK_SIZE = 3;
62	const COMPONENT_BLOCK_PREMIUM = 60;
63	
64	const countByType = (items: Item[]): Map<string, number> => {
65	  const counts = new Map<string, number>();
66	  for (const item of items) {
67	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
68	  }
69	  return counts;
70	};
71	
72	// A building block of 3 alike components is offered at a special base premium.
73	const sumBasePremiums = (items: Item[]): number => {
74	  let total = 0;
75	  for (const [type, count] of countByType(items)) {
76	    total =
77	      count === COMPONENT_BLOCK_SIZE
78	        ? total + COMPONENT_BLOCK_PREMIUM
79	        : total + count * basePremiumFor({ type });
80	  }
81	  return total;
82	};
83	
84	// Premiums are rounded up, in the MHPCO's favour; only the final premium is
85	// rounded, intermediate amounts stay fractional.
86	const roundInMHPCOsFavour = Math.ceil;
87	
88	const quotePremium = (items: Item[]): number => {
89	  const basePremium = sumBasePremiums(items);
90	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
91	  return roundInMHPCOsFavour(
92	    basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
93	  );
94	};
95	
96	const runStep = (step: Step): QuoteResult | ClaimResult => {
97	  switch (step.op) {
98	    case "quote":
99	      return { premium: quotePremium(step.items) };
100	    case "claim":
101	      throw new Error("claim steps are not supported yet");
102	  }
103	};
104	
105	export const runScenario = (scenario: Scenario): ScenarioResults => ({
106	  results: scenario.steps.map(runStep),
107	});
